#!/usr/bin/env bash
# Generates .env with random secrets. An existing .env is never overwritten.
set -Eeuo pipefail
cd "$(dirname "$0")"

if [ -f .env ]; then
    echo ".env already exists, keeping it"
    exit 0
fi

rand() { openssl rand -hex "${1:-16}"; }

cat > .env <<EOF
# Generated by setup.sh. Do not commit.

# Published ports (HAProxy)
HTTP_PORT=8080
STATS_PORT=8404

# Host names Drupal answers to (comma separated)
DRUPAL_TRUSTED_HOSTS=localhost,127.0.0.1

# Site and first administrator (created once, on first start)
DRUPAL_SITE_NAME="Drupal HA"
DRUPAL_ADMIN_USER=admin
DRUPAL_ADMIN_PASSWORD=$(rand 12)
DRUPAL_ADMIN_EMAIL=admin@example.com

# Database
DRUPAL_DB_NAME=drupal
DRUPAL_DB_USER=drupal
DRUPAL_DB_PASSWORD=$(rand)

# Identical on every node
DRUPAL_HASH_SALT=$(rand 32)

# HAProxy stats page (http://127.0.0.1:8404/stats)
STATS_USER=admin
STATS_PASSWORD=$(rand 12)
EOF
chmod 600 .env
echo "wrote .env"
